import json
from pathlib import Path
import shutil
import subprocess
import sys

import pytest

REPO = Path(__file__).resolve().parents[1]
PROBE = 'import contextlib\nimport hashlib\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport secrets\nimport sys\n\nrepo, root, mode, state, output = sys.argv[1:6]\nrepo, root, output = Path(repo), Path(root), Path(output)\nroot.mkdir(parents=True, exist_ok=False)\nfor name, part in {\n    \'LOCALAPPDATA\':\'local\', \'APPDATA\':\'roaming\', \'PROGRAMDATA\':\'program\',\n    \'LABEL_MATCH_SAVE_DIR\':\'data\', \'LABEL_MATCH_SETTINGS_PATH\':\'settings/input.json\',\n    \'LABEL_MATCH_LOGISTICS_PROFILE_PATH\':\'profile/input.json\',\n    \'LABEL_MATCH_DIRECT_SYNC_ROOT\':\'sync\', \'KMTECH_LABEL_WRITER_CONTROL_ROOT\':\'control\',\n    \'TEMP\':\'temp\', \'TMP\':\'temp\',\n}.items():\n    os.environ[name]=str(root/part)\nos.environ[\'KMTECH_LABEL_WRITER_TEST_MODE\']=\'1\'\nfor name in (\'LABEL_MATCH_ENROLLMENT_TLS_CA_BUNDLE_PATH\',\n             \'LABEL_MATCH_LOGISTICS_TLS_CA_BUNDLE_PATH\',\n             \'KMTECH_LABEL_CONFLICT_RESOLUTION_RECEIPT_PATH\',\n             \'LABEL_MATCH_PROTECTED_ADMIN_PROFILE\'):\n    os.environ.pop(name,None)\nsys.path.insert(0,str(repo))\nimport protected_admin\nimport label_data_generation as generation\nfrom kmtech_shared.data_generation import record_generation\nimport label_match_product_host as entry\nimport direct_sync_runtime as runtime\nfrom direct_sync_push import DEFAULT_ENDPOINT_PATH\nimport requests\nsubject=\'-\'.join(map(str,(\'S\',1,5,21,266,901,902,1001)))\nprotected_admin.current_process_sid=lambda:subject\nexternal=root/\'external\' if mode==\'explicit\' else root/\'local\'/\'CompanyProducerConnector\'\nexternal.mkdir(parents=True)\ntarget=external/\'secrets\'/(secrets.token_hex(8)+\'.dpapi\')\ntarget.parent.mkdir()\ntarget.write_bytes(secrets.token_bytes(32))\ncredential = root / "locator" / "credential.json"\ncredential.parent.mkdir()\npayload={\'producer_id\':secrets.token_hex(8),\'key_id\':secrets.token_hex(8),\n         \'secret_ref\':\'dpapi:\'+target.stem,\n         \'endpoint_url\':\'https://example.invalid\'+DEFAULT_ENDPOINT_PATH}\nif mode==\'explicit\': payload[\'secret_data_dir\']=str(external)\ncredential.write_text(json.dumps(payload),encoding=\'utf-8\')\nimport subprocess\nlegacy_kind, legacy_shell = sys.argv[6:8]\nlegacy_source = root / "legacy-source"\n(legacy_source / "runtime").mkdir(parents=True)\n(legacy_source / "app").mkdir()\n(legacy_source / "runtime/pythonw.exe").write_bytes(b"isolated native launcher stand-in")\n(legacy_source / "app/main.py").write_text("pass\\n", encoding="utf-8")\nlegacy_static = "v2.0.94"\nlegacy_code = legacy_source / "app/Label_Match.py"\nlegacy_code.write_text("APP_VERSION = " + repr(legacy_static) + "\\n", encoding="utf-8")\nlegacy_manifest = {"schema": "label-match-portable-tree-v1", "source_commit": generation.release_identity(repo)["build_id"]}\nif legacy_kind in {"manifest-mismatch", "unchecked-version"}:\n    legacy_manifest["version"] = generation.CURRENT_VERSION\n(legacy_source / "portable-manifest.json").write_text(json.dumps(legacy_manifest), encoding="utf-8")\nif legacy_kind not in {"unsealed", "unchecked-version"}:\n    seal_script = root / "seal.ps1"\n    seal_script.write_text("param($Helper,$Repo,$Root)\\n. $Helper -SharedCodeRoot $Repo\\n[void](Write-BootstrapIntegrityRecord -Root $Root -CodeRoot $Root)\\n", encoding="utf-8-sig")\n    seal = subprocess.run([legacy_shell, "-NoProfile", "-File", str(seal_script), str(repo / "tools/bootstrap_integrity.ps1"), str(repo), str(legacy_source)], capture_output=True, creationflags=subprocess.CREATE_NO_WINDOW)\n    (root / "seal.stdout").write_bytes(seal.stdout)\n    (root / "seal.stderr").write_bytes(seal.stderr)\n    if seal.returncode != 0:\n        raise RuntimeError("existing bootstrap producer failed")\nif legacy_kind == "static-mismatch":\n    legacy_code.write_text("APP_VERSION = \'v2.0.93\'\\n", encoding="utf-8")\nidentity = {"version": legacy_static, "build_id": legacy_manifest["source_commit"]}\nmarker=external/\'data-generation.json\'\nif state!=\'absent\':\n    record_generation(marker,generation.CURRENT_VERSION if state == \'higher\' else identity[\'version\'],\n        app_id=generation.APP_ID,subject_sid=subject,build_id=str(identity[\'build_id\']))\n    if state==\'unknown\': marker.write_bytes(b\'{}\')\nevents={\'secret_reads\':0,\'decrypt_calls\':0,\'downstream_calls\':0,\'network_calls\':0,\'native_calls\':0}\ndef decrypt(_):\n    events[\'decrypt_calls\']+=1\n    return secrets.token_hex(32).encode()\nruntime._dpapi_unprotect_current_user=decrypt\ndef downstream(**kwargs):\n    events[\'downstream_calls\']+=1\n    return {\'status\':\'READY\'}\nentry.restore_relay_spool_from_server=downstream\ndef blocked_network(*a,**k):\n    events[\'network_calls\']+=1\n    raise AssertionError(\'network blocked\')\nrequests.sessions.Session.request=blocked_network\nimport winreg\ndef blocked_native(*a,**k):\n    events[\'native_calls\']+=1\n    raise AssertionError(\'native mutation blocked\')\nwinreg.SetValueEx=winreg.DeleteValue=blocked_native\ndef snapshot():\n    return {str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest()\n            for p in root.rglob(\'*\') if p.is_file()}\nos.environ[\'LABEL_MATCH_DIRECT_SYNC_ROOT\'] = str(credential.parent)\nbefore=snapshot()\ndirect_refused=False\ntry: generation.check_user_data_open(repo,(external,))\nexcept generation.DataGenerationError: direct_refused=True\noriginal=Path.open\ndef observed(path,mode=\'r\',*a,**k):\n    if Path(path) == credential and \'r\' in mode: events[\'locator_reads\'] = events.get(\'locator_reads\', 0) + 1\n    if Path(path).resolve()==target.resolve() and \'r\' in mode:events[\'secret_reads\']+=1\n    return original(path,mode,*a,**k)\nPath.open=observed\nstdout,stderr=io.StringIO(),io.StringIO()\nerror_type=\'\'\nwith contextlib.redirect_stdout(stdout),contextlib.redirect_stderr(stderr):\n    try:\n        code=entry.dispatch_product_mode([\'--onboard-current-user\', \'--app-root\', str(legacy_source), \'--check-data-generation-only\'])\n    except Exception as exc:\n        code=-1;error_type=type(exc).__name__\nPath.open=original\nafter=snapshot()\nadded=set(after)-set(before)\nresult={\'mode\':mode,\'state\':state,\'code\':code,\'error_type\':error_type,\n        \'direct_external_refused\':direct_refused,**events,\'new_files\':len(added),\n        \'generation_records\':sum(n.endswith(\'data-generation.json\') or \'data-generation/\' in n.replace(\'\\\\\',\'/\') for n in added),\n        \'existing_changed\':sum(after.get(n)!=v for n,v in before.items()),\n        \'scope\':\'real operator main/guard/record/credential and secret reader; synthetic SID/decrypt/downstream; network/native blocked\'}\nresult[\'locator_reads\'] = events.get(\'locator_reads\', 0)\noutput.write_text(json.dumps(result,indent=2),encoding=\'utf-8\')\nprint(json.dumps(result))\n\nraise SystemExit(result[\'code\'] if result[\'code\'] is not None else 1)\n'


@pytest.mark.parametrize("shell", ["powershell", "pwsh"])
@pytest.mark.parametrize("kind", ["valid", "higher", "static-mismatch", "manifest-mismatch", "unsealed", "unchecked-version"])
def test_read_only_installer_admission_binds_legacy_source_bytes(tmp_path, shell, kind):
    executable = shutil.which(shell)
    if executable is None:
        pytest.skip("PowerShell is unavailable")
    probe = tmp_path / "probe.py"
    probe.write_text(PROBE, encoding="utf-8")
    output = tmp_path / "result.json"
    state = "higher" if kind == "higher" else "same"
    run = subprocess.run([sys.executable, "-B", str(probe), str(REPO), str(tmp_path / "application"),
        "explicit", state, str(output), kind, executable], capture_output=True, timeout=60,
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    assert output.is_file()
    data = json.loads(output.read_text(encoding="utf-8-sig"))
    assert run.returncode == (0 if kind == "valid" else 4)
    assert data["code"] == (0 if kind == "valid" else 4)
    assert data["new_files"] == 0
    assert data["existing_changed"] == 0
    assert data["generation_records"] == 0
    assert data["secret_reads"] == 0
    assert data["decrypt_calls"] == 0
    assert data["native_calls"] == 0
    assert data["network_calls"] == 0
    assert data["error_type"] == ""
